//! The genesis record: the one entry every ledger seeded from this code
//! begins with - the lineage mark of the DATU project (a DAG-type
//! accountability ledger, not a blockchain).
//!
//! Minted once (see `examples/mint_genesis.rs`) by the founder's dedicated
//! keypair; the signature covers the founder's statement, so no one - not
//! even a fork - can forge a record claiming this lineage. Forks that keep
//! this constant descend from it; forks that mint their own genesis (the
//! example is the tool) walk their own. The private halves live with the
//! founder (`~/.datu-genesis/`), never in this repo.
//!
//! [`Store::open`](datu_store::Store) seeds this entry into every new and
//! existing ledger below the writer policy: policy gates what *peers* may
//! land; the genesis is the ledger's own definition, carried by the code.

use crate::entry::Entry;
use crate::error::{Error, Result};
use borsh::BorshDeserialize;
use std::sync::OnceLock;

/// Namespace of the genesis record.
pub const NS_GENESIS: &str = "genesis";
/// Founder, exactly as written inside the record payload.
pub const GENESIS_FOUNDER: &str = "EB. Secretaria aka greenarmor";
/// Ed25519 author key of the minted record (hex).
pub const GENESIS_AUTHOR_HEX: &str = "b21a2df8016f6a387388f462c6799558c9b25a012f00352f1bd2e8b075018666";
/// BLAKE3 entry id of the minted record (hex).
pub const GENESIS_ID_HEX: &str = "37616bce5bfb8b773f7c99a9e52bcd7aa43294301ab074a908fbc9a334315d63";
/// The signed genesis entry (borsh, hex): Ed25519 + ML-DSA-65 over the
/// founder's statement. The statement text lives *only* here.
const GENESIS_ENTRY_HEX: &str = "";

static GENESIS: OnceLock<Entry> = OnceLock::new();

/// The decoded, fully verified genesis entry (cached). Any tampering with
/// the constant fails here: the signature, the id and the author key are
/// all cross-checked before the record is ever used.
pub fn genesis_entry() -> Result<&'static Entry> {
    if let Some(entry) = GENESIS.get() {
        return Ok(entry);
    }
    let bytes = hex::decode(GENESIS_ENTRY_HEX)
        .map_err(|e| Error::InvalidEntry(format!("genesis constant is not hex: {e}")))?;
    let entry = Entry::try_from_slice(&bytes)
        .map_err(|e| Error::InvalidEntry(format!("genesis constant does not decode: {e}")))?;
    entry.verify()?;
    let id = entry.id()?;
    if hex::encode(id) != GENESIS_ID_HEX {
        return Err(Error::InvalidEntry(
            "genesis constant id mismatch - the record was tampered with".into(),
        ));
    }
    if entry.body.author != GENESIS_AUTHOR_HEX {
        return Err(Error::InvalidEntry(
            "genesis constant author mismatch - the record was tampered with".into(),
        ));
    }
    if entry.body.namespace != NS_GENESIS || entry.body.seq != 0 {
        return Err(Error::InvalidEntry(
            "genesis constant is not a genesis record (namespace/seq)".into(),
        ));
    }
    let _ = GENESIS.set(entry);
    Ok(GENESIS.get().expect("just set"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn genesis_verifies_and_carries_the_statement_once() {
        let entry = genesis_entry().expect("embedded genesis must verify");
        assert_eq!(entry.body.namespace, NS_GENESIS);
        assert_eq!(entry.body.seq, 0);
        let payload: serde_json::Value = serde_json::from_slice(&entry.body.payload).unwrap();
        assert_eq!(payload["founder"], GENESIS_FOUNDER);
        assert_eq!(payload["kind"], "genesis");
        assert_eq!(payload["project"], "DATU — a DAG-type accountability ledger, not a blockchain");
        let statement = payload["statement"].as_str().unwrap();
        // No redundant messaging: the statement carries its headline exactly once.
        assert_eq!(statement.matches("The Greatest Life Hack").count(), 1);
        assert!(statement.contains("Self-Learning"));
    }
}
